INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(40811, 'Ezra 7:1', 'Ezra', 7, 1, 'وروسته له ډېرو کلونو څخه کله چې ارتخششتا د فارس پاچا ؤ، د عزرا په نوم یو سړی ؤ چې شجره یې تر لوی کاهن هارون پورې رسېدله. د هغه شجره په لاندې ډول وه: عزرا د سرایا زوې ؤ، سرایا د عزریا زوی ؤ، عزریا د حلقیا زوی ؤ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_1.mp3', '', 1761754199, 1761754199),
(40812, 'Ezra 7:2', 'Ezra', 7, 2, 'حلقیا د شلوم زوی ؤ، شلوم د صادوق زوی ؤ، صادوق د اخیطوب زوی ؤ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_2.mp3', '', 1761754199, 1761754199),
(40813, 'Ezra 7:3', 'Ezra', 7, 3, 'اخیطوب د امریا زوی ؤ، امریا د عزریا زوی ؤ، عزریا د مرایوت زوی ؤ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_3.mp3', '', 1761754199, 1761754199),
(40814, 'Ezra 7:4', 'Ezra', 7, 4, 'مرایوت د زرحیا زوی ؤ، زرحیا د عزي زوی ؤ، عزي د بقي زوی ؤ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_4.mp3', '', 1761754199, 1761754199),
(40815, 'Ezra 7:5', 'Ezra', 7, 5, 'بقي د ابیشوع زوی ؤ، ابیشوع د فینحاس زوی ؤ، فینحاس د العازار زوی ؤ او العازار د لوی کاهن هارون زوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_5.mp3', '', 1761754199, 1761754199),
(40816, 'Ezra 7:10', 'Ezra', 7, 10, 'دا مرسته ځکه ورسره وشوه چې عزرا خپل ژوند د څښتن د شریعت زده کړې ته، په هغه باندې عمل کولو او د اسراییلو خلکو ته د شریعت د حکمونو او قوانینو ورزده کولو ته وقف کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_10.mp3', '', 1761754199, 1761754199),
(40817, 'Ezra 7:11', 'Ezra', 7, 11, 'ارتخششتا پاچا دا لاندېنی لیک عزرا ته چې کاهن او دیني عالم ؤ، ورکړ. ځکه چې هغه په هغو قوانینو او حکمونو باندې ښه پوهېده چې څښتن اسراییلو ته ورکړي وو:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_11.mp3', '', 1761754199, 1761754199),
(40818, 'Ezra 7:12', 'Ezra', 7, 12, '«د ارتخششتا، د پاچاهانو پاچا له خوا عزرا کاهن ته چې د اسمانونو د خدای د شریعت عالم دی، سلامونه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_12.mp3', '', 1761754199, 1761754199),
(40819, 'Ezra 7:13', 'Ezra', 7, 13, 'زه په دې توګه امر کوم چې د اسراییلو هغو ټولو خلکو، د هغوی کاهنانو او لاویانو ته چې زما په ټوله امپراتورۍ کې دي او غواړي چې ستا سره اورشلیم ته لاړ شي، اجازه ورکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_13.mp3', '', 1761754199, 1761754199),
(40820, 'Ezra 7:14', 'Ezra', 7, 14, 'ما د خپلو اووه مشاورانو سره یوځای پرېکړه وکړه چې تا عزرا ولېږم چې په اورشلیم او یهودا کې حالات وڅېړې او وګورې چې ستا د خدای شریعت چې تاته سپارل شوی دی، څنګه ورڅخه اطاعت کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_14.mp3', '', 1761754199, 1761754199),
(40821, 'Ezra 7:15', 'Ezra', 7, 15, 'ته باید د سرو او سپینو زرو هغه نذرانې د ځان سره یوسې چې زه او زما مشاوران غواړو هغه د اسراییلو خدای ته چې کور یې په اورشلیم کې دی، ورکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_15.mp3', '', 1761754199, 1761754199),
(40822, 'Ezra 7:16', 'Ezra', 7, 16, 'ته باید هغه سپین او سره زر چې د بابل د ټولې سیمې څخه یې راټولوې او هغه نذرانې چې د اسراییلو خلک او کاهنان یې په خپله خوښه اورشلیم کې د خپل خدای کور ته ورکوي، هم یوسې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_16.mp3', '', 1761754199, 1761754199),
(40823, 'Ezra 7:17', 'Ezra', 7, 17, 'ته باید دا پیسې په ډېر پام سره ولګوې او په هغو باندې غویان، پسونه، وري، غلې دانې او شراب واخلې او هغه په اورشلیم کې ستاسو د خدای د کور د قربانۍ په ځای باندې قرباني کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_17.mp3', '', 1761754199, 1761754199),
(40824, 'Ezra 7:18', 'Ezra', 7, 18, 'هرڅه چې تاته او ستا ملګرو ته ښه ښکاري د هغو دپاره د پاتې سپینو او سرو زرو څخه د خپل خدای د رضا سره سم ولګوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_18.mp3', '', 1761754199, 1761754199),
(40825, 'Ezra 7:19', 'Ezra', 7, 19, 'هغه لوښي چې تاته ستا د خدای د کور په کارونو کې د کارولو دپاره درکړل شوي دي، هغه ټول د اورشلیم خدای ته وړاندې کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_19.mp3', '', 1761754199, 1761754199),
(40826, 'Ezra 7:20', 'Ezra', 7, 20, 'ستا د خدای د کور دپاره هر شي ته چې اړتیا وي، ته کولای شې چې د شاهي خزانې څخه یې واخلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_20.mp3', '', 1761754199, 1761754199),
(40827, 'Ezra 7:21', 'Ezra', 7, 21, 'زه ارتخششتا د فرات د سیند د لوېدیځې خوا سیمې ټولو خزانه دارانو ته امر کوم چې هرڅه چې کاهن او د اسمانونو د خدای د شریعت عالم عزرا یې ستاسو څخه غواړي، هغه ورته زر تیار کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_21.mp3', '', 1761754199, 1761754199),
(40828, 'Ezra 7:22', 'Ezra', 7, 22, 'هغه ته تر درې زره او څلور سوه کیلو ګرامو پورې سپین زر، لس ټنه غنم، دوه زره لیتره شراب، دوه زره لیتره د زیتونو تېل او هرڅومره مالګې ته چې اړتیا ولري، ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_22.mp3', '', 1761754199, 1761754199),
(40829, 'Ezra 7:23', 'Ezra', 7, 23, 'هرڅه چې د اسمانونو خدای یې د خپل کور دپاره غواړي باید هغه ورته په احتیاط سره تیار کړئ. هغه کار ونه کړئ چې څښتن په ما او په هغو پاچاهانو باندې چې زما څخه وروسته راځي، په قهر شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_23.mp3', '', 1761754199, 1761754199),
(40830, 'Ezra 7:24', 'Ezra', 7, 24, 'تاسو ته اجازه نشته چې د کاهنانو، لاویانو، سندرغاړو، ساتونکو، خدمتګارانو او هغو نورو کارګرانو څخه چې د خدای د دې کور پورې تړاو لري باج او مالیه راټوله کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_24.mp3', '', 1761754199, 1761754199),
(40831, 'Ezra 7:25', 'Ezra', 7, 25, 'ای ښاغلیه عزرا! د هغه حکمت له مخې چې خدای تاته درکړی دی، مدیران او قاضیان وټاکه چې په هغو خلکو باندې حکومت وکړي چې د فرات د سیند په لوېدیځې خوا کې دي او ستاسو د خدای د حکمونو لاندې خپل ژوند تېروي. هغه څوک چې په هغو حکمونو باندې نه پوهیږي باید هغوی ته یې ورزده کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_25.mp3', '', 1761754199, 1761754199),
(40832, 'Ezra 7:26', 'Ezra', 7, 26, 'که چېرې څوک ستاسو د خدای د قوانینو یا د پاچا د قوانینو څخه سرغړونه وکړي، هغوی ته باید ډېر زر سزا ورکړل شي. یا دې هغوی ووژل شي، یا دې د وطن څخه وشړل شي، یا دې د هغوی شتمني ورڅخه واخیستل شي او یا دې بندي شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_26.mp3', '', 1761754199, 1761754199),
(40833, 'Ezra 7:27', 'Ezra', 7, 27, 'عزرا وویل: «زمونږ د نیکونو څښتن خدای ته دې ثنا وي! هغه پاچا دې ته راضي کړ چې په دې ډول په اورشلیم کې د څښتن د کور عزت او درنښت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_27.mp3', '', 1761754199, 1761754199),
(40834, 'Ezra 7:28', 'Ezra', 7, 28, 'څښتن په ما باندې پاچا، د هغه مشاوران او لوړ رتبه درباریان مهربانه کړل. زما څښتن خدای ماته دا توان راکړ ترڅو وکولای شم د اسراییلو د قوم مشران راټول کړم چې زما سره بېرته اورشلیم ته راشي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra7_verse_28.mp3', '', 1761754199, 1761754199),
(40835, 'Ezekiel 41:1', 'Ezekiel', 41, 1, 'وروسته بیا هغه سړي زه د عبادت د ځای اصلي کوټې یعنې سپېڅلي ځای ته بوتلم. هغه د دې کوټې د دروازې د دواړو خواوو چوکاټونه اندازه کړل او د هر یو پنډوالی درې متره ؤ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_1.mp3', '', 1761754199, 1761754199),
(40836, 'Ezekiel 41:2', 'Ezekiel', 41, 2, 'دروازه پنځه متره پراخه وه او د هغې د دواړو خواو د دېوالونو پراخوالی دوه نیم متره ؤ. هغه همدا کوټه اندازه کړه، د هغې اوږدوالی شل متره او سور یې لس متره ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_2.mp3', '', 1761754199, 1761754199),
(40837, 'Ezekiel 41:3', 'Ezekiel', 41, 3, 'بیا هغه دې کوټې ته لاړ چې د ټولو په منځ کې وه. هغه د کوټې د دروازې چوکاټ اندازه کړ چې پنډوالی یې یو متر ؤ. دروازه درې متره پراخه وه او د هغې د دواړو خواوو دېوالونه درې نیم متره پراخ وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_3.mp3', '', 1761754199, 1761754199),
(40838, 'Ezekiel 41:4', 'Ezekiel', 41, 4, 'هغه بیا همدا کوټه اندازه کړه چې هغه لس متره مربع وه. دا کوټه د اصلي کوټې شاته وه. بیا هغه ماته وویل: «دا ډېر سپېڅلی ځای دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_4.mp3', '', 1761754199, 1761754199),
(40839, 'Ezekiel 41:5', 'Ezekiel', 41, 5, 'هغه سړي د عبادتځای دېوال اندازه کړ او د هغه پنډوالی درې متره ؤ. د دې دېوال دباندې د عبادتځای ګردچاپېره یو شمېر کوچنۍ کوټې وې چې دوه متره یې سور ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_5.mp3', '', 1761754199, 1761754199),
(40840, 'Ezekiel 41:6', 'Ezekiel', 41, 6, 'دا کوټې په درې منزلونو کې جوړې شوې وې چې په هر منزل کې یې دېرش کوټې وې. د عبادت د ځای ګردچاپېره په دېوالونو کې څنډې وې چې دا کوټې به یې ټینګولې، ترڅو کوټې په خپله د ودانۍ په دېوال کې نښتې نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_6.mp3', '', 1761754199, 1761754199),
(40841, 'Ezekiel 41:7', 'Ezekiel', 41, 7, 'د عبادتځای شاوخوا کوټې داسې جوړې شوې وې. څنګه چې څوک په کې پورته کېده، هغه پراخه کېدلې. د لاندېني منزل څخه د منځني منزل له لارې تر پاسني منزل پورې یوه زینه ختلې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_7.mp3', '', 1761754199, 1761754199),
(40842, 'Ezekiel 41:8', 'Ezekiel', 41, 8, 'ما ولیدل چې د عبادتځای په یو بنیاد باندې ولاړ ؤ. د عبادتځای شاوخوا یوه صفه وه چې درې متره لوړه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_8.mp3', '', 1761754199, 1761754199),
(40843, 'Ezekiel 41:12', 'Ezekiel', 41, 12, 'د عبادت د ځای لوېدیځ خواته یو خالی ځای ؤ. لوېدیځ خواته په اخر سر کې یوه ودانۍ وه چې اوږدوالی یې پنځه څلوېښت متره او سور یې پنځه دېرش متره ؤ. د هغې د ګردچاپېره دېوالونو پنډوالی دوه نیم متره ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_12.mp3', '', 1761754199, 1761754199),
(40844, 'Ezekiel 41:13', 'Ezekiel', 41, 13, 'هغه سړي د بهر څخه د عبادت د ځای اصلي ودانۍ اندازه کړه چې د هغې اوږدوالی پنځوس متره ؤ. هغه د عبادت د ځای د ودانۍ د شا د دېوال څخه د خالي ځای په شمول تر لوېدیځې ودانۍ د بهرني دېوال پورې مساحت اندازه کړ چې د هغه اوږدوالی هم پنځوس متره ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_13.mp3', '', 1761754199, 1761754199),
(40845, 'Ezekiel 41:14', 'Ezekiel', 41, 14, 'ختیځې خواته د عبادت د ځای د حوېلۍ سور چې په هغې کې د عبادت د ځای مخه هم شامله وه، پنځوس متره ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_14.mp3', '', 1761754199, 1761754199),
(40846, 'Ezekiel 41:15', 'Ezekiel', 41, 15, 'هغه د لوېدیځې ودانۍ بهرنی اوږدوالی اندازه کړ چې په هغې کې د دېوالونو د دواړو خواو څنډې هم شاملې وي، هغه هم پنځوس متره ؤ. د عبادت د ځای د ودانۍ تفصیلات د عبادت د ځای د اصلي کوټې دننني دېوالونه، دهلېز،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_15.mp3', '', 1761754199, 1761754199),
(40847, 'Ezekiel 41:16', 'Ezekiel', 41, 16, 'د دروازو خولې، وړې کړکۍ‌ګانې او هغه درې څنډې چې د دې کوټو شاوخوا وې، همدارنګه د دروازې د خولې په مخکې دېوالونه د غولي څخه تر وړو کړکیو پورې د تړل شویو کړکۍ‌ګانو په شمول، دا ټول په لرګیو پوښل شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_16.mp3', '', 1761754199, 1761754199),
(40848, 'Ezekiel 41:17', 'Ezekiel', 41, 17, 'د دروازې دپاسه دېوال، د عبادت د ځای په دنننه او دباندې او د هغه د شاوخوا په ټولو دېوالونو باندې که دنننه وو او که دباندې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_17.mp3', '', 1761754199, 1761754199),
(40849, 'Ezekiel 41:18', 'Ezekiel', 41, 18, 'د اسماني مخلوقاتو او د خرما د ونو نقشونه ویستل شوي وو. مخکې یوه ونه وه، بیا یو اسماني مخلوق ؤ، ونه او اسماني مخلوق په دې ډول ویستل شوي وو. دغو اسماني مخلوقاتو هر یو دوه دوه مخونه درلودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_18.mp3', '', 1761754199, 1761754199),
(40850, 'Ezekiel 41:21', 'Ezekiel', 41, 21, 'د اصلي کوټې د دروازې چوکاټونه مربع شکله وو. د ډېر سپېڅلي ځای د دروازې د چوکاټ لرګي هم د دې په شان وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_21.mp3', '', 1761754199, 1761754199),
(40851, 'Ezekiel 41:22', 'Ezekiel', 41, 22, 'د لرګيو نه جوړ شوی د قربانۍ د ځای لوړوالی یونیم متر او مساحت یې یو متر مربع ؤ. د هغه د کنج پایې، بنیاد او د هغه خواوې ټولې د لرګیو نه جوړې شوې وې. هغه سړي ماته وویل: «دا هغه مېز دی چې د څښتن په حضور کې ایښودل کیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_22.mp3', '', 1761754199, 1761754199),
(40852, 'Ezekiel 41:23', 'Ezekiel', 41, 23, 'د عبادت ځای لویي کوټي یعنې سپېڅلي ځای او ډېر سپېڅلي ځای دوه، دوه پرله پسې دروازې درلودلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_23.mp3', '', 1761754199, 1761754199),
(40853, 'Ezekiel 41:24', 'Ezekiel', 41, 24, 'دې دروازو دوه پلې درلودلې چې هره دروازه به د منځ نه خلاصېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_24.mp3', '', 1761754199, 1761754199),
(40854, 'Ezekiel 41:25', 'Ezekiel', 41, 25, 'د عبادت د ځای د لویي کوټې دروازې هم د دېوالونو په شان د خرما د ونو او اسماني مخلوقاتو په نقشونو باندې ښکلې کړای شوې وې. د دهلېز د دروازې په باندیني ځای باندې د لرګیو چترۍ لګول شوې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_25.mp3', '', 1761754199, 1761754199),
(40855, 'Ezekiel 41:26', 'Ezekiel', 41, 26, 'د دې کوټې په اړخونو کې وړې کړکۍ‌ګانې وې او دېوالونه یې د خرما د ونو په نقشونو باندې ښکلي کړای شوي وو. د عبادت د ځای نورو کوټو هم چترۍ‌ګانې درلودلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel41_verse_26.mp3', '', 1761754199, 1761754199),
(40856, 'Job 28:1', 'Job', 28, 1, '”بې‌شکه چې د سپينو زرو يو کان وى، او د سرو زرو د صفا کولو دپاره يو ځائ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_1.mp3', '', 1761754199, 1761754199),
(40857, 'Job 28:2', 'Job', 28, 2, 'اوسپنه د زمکې نه راويستلے شى، او د کاڼو نه ويلې شوې تانبه راوځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_2.mp3', '', 1761754199, 1761754199),
(40858, 'Job 28:3', 'Job', 28, 3, 'انسان په تيارۀ کښې رڼا ځلوى، او د دُنيا آخرى حد معلوموى، او د زمکې لاندې په تيارۀ کښې قيمتى کاڼى لټوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_3.mp3', '', 1761754199, 1761754199),
(40859, 'Job 28:4', 'Job', 28, 4, 'هغوئ د انسان د اوسېدو نه لرې په زمکه کښې سورنګونه جوړوى، هغوئ په کان کښې په پړو باندې کوزيږى او خېژى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_4.mp3', '', 1761754199, 1761754199),
(40860, 'Job 28:5', 'Job', 28, 5, 'په دې زمکه پاس خوراک لوئيږى خو دا زمکه لاندې داسې ده لکه د اور.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_5.mp3', '', 1761754199, 1761754199),
(40861, 'Job 28:6', 'Job', 28, 6, 'د دې زمکې په کاڼو کښې نيلم شته، او د دې په خاوره کښې سرۀ زر پراتۀ دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_6.mp3', '', 1761754199, 1761754199),
(40862, 'Job 28:7', 'Job', 28, 7, 'د هغه خزانې لار يو ښکارى مارغۀ ته هم نۀ ده معلومه، او نۀ باز هغه ليدلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_7.mp3', '', 1761754199, 1761754199),
(40863, 'Job 28:8', 'Job', 28, 8, 'ځنګلى ځناورو په هغې باندې قدم نۀ دے اېښے، او زمرے په هغې باندې تېر شوے نۀ دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_8.mp3', '', 1761754199, 1761754199),
(40864, 'Job 28:9', 'Job', 28, 9, 'بنى آدم په سختو کاڼو کښې کار کوى، او د غرونو بېخونه اړَوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_9.mp3', '', 1761754199, 1761754199),
(40865, 'Job 28:10', 'Job', 28, 10, 'هغوئ په کاڼو کښې سورنګونه جوړوى، او هغوئ قيمتى کاڼى پېدا کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_10.mp3', '', 1761754199, 1761754199),
(40866, 'Job 28:11', 'Job', 28, 11, 'هغوئ د دريابونو بېخونه لټوى، او هغوئ پټ څيزونه رڼا ته راوباسى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_11.mp3', '', 1761754199, 1761754199),
(40867, 'Job 28:12', 'Job', 28, 12, 'خو هغوئ ته پته نشته چې حِکمت به چرته ملاويږى؟ او د پوهې ځائ چرته دے؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_12.mp3', '', 1761754199, 1761754199),
(40868, 'Job 28:13', 'Job', 28, 13, 'بنى آدم د دې د قيمت نه خبر نۀ دے، او دا په دې دُنيا کښې نۀ ملاويږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_13.mp3', '', 1761754199, 1761754199),
(40869, 'Job 28:14', 'Job', 28, 14, 'سمندر وائى چې دا په ما کښې نشته، او درياب وائى چې دا په ما کښې نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_14.mp3', '', 1761754199, 1761754199),
(40870, 'Job 28:15', 'Job', 28, 15, 'نۀ دا په سپينو زرو اخستلے شى، او نۀ دا په سرو زرو اخستلے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_15.mp3', '', 1761754199, 1761754199),
(40871, 'Job 28:16', 'Job', 28, 16, 'د اوفير سرۀ زر د دې قيمت نۀ شى پوره کولے، نۀ يې اونيکس کاڼى او نۀ يې نيلم کاڼى پوره کولے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_16.mp3', '', 1761754199, 1761754199),
(40872, 'Job 28:17', 'Job', 28, 17, 'سرۀ زر او قيمتى کاڼى د حِکمت برابر نۀ شى کېدے، او نۀ دا د سوچه سرو زرو په کالو باندې بدلولے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_17.mp3', '', 1761754199, 1761754199),
(40873, 'Job 28:18', 'Job', 28, 18, 'مرجان او بلور غمى هيڅ هم نۀ دى، د حِکمت قيمت د ملغلرو نه اوچت دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_18.mp3', '', 1761754199, 1761754199),
(40874, 'Job 28:19', 'Job', 28, 19, 'د ايتهوپيا طوپاز د دې برابر نۀ دے، او نۀ سوچه سرۀ زر د دې قيمت پوره کولے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_19.mp3', '', 1761754199, 1761754199),
(40875, 'Job 28:20', 'Job', 28, 20, 'نو بيا حِکمت د کوم ځائ نه راځى؟ او د پوهې مقام چرته دے؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_20.mp3', '', 1761754199, 1761754199),
(40876, 'Job 28:21', 'Job', 28, 21, 'دا د ټول مخلوق د سترګو نه پناه دے، او د هوا د مارغانو نه پټ دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_21.mp3', '', 1761754199, 1761754199),
(40877, 'Job 28:22', 'Job', 28, 22, 'په عالمِ ارواح کښې صرف د دې افواه اورېدلے شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_22.mp3', '', 1761754199, 1761754199),
(40878, 'Job 28:23', 'Job', 28, 23, 'صرف خُدائ پاک د حِکمت په طريقه پوهه دے، او هغۀ ته د دې د مقام پته ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_23.mp3', '', 1761754199, 1761754199),
(40879, 'Job 28:24', 'Job', 28, 24, 'ځکه چې هغه ټولې دُنيا ته ګورى، او هغه د آسمانونو لاندې هر يو څيز وينى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_24.mp3', '', 1761754199, 1761754199),
(40880, 'Job 28:25', 'Job', 28, 25, 'کله چې هغۀ هوا ته طاقت ورکړو، او په وريځو کښې يې باران کېښودو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_25.mp3', '', 1761754199, 1761754199),
(40881, 'Job 28:26', 'Job', 28, 26, 'کله چې هغۀ د باران دپاره اصُول مقرر کړل، او د تندر دپاره يې يوه لاره مقرره کړه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_26.mp3', '', 1761754199, 1761754199),
(40882, 'Job 28:27', 'Job', 28, 27, 'بيا هغۀ حِکمت وليدو او د دې اندازه يې واخستله، هغۀ دا تيار کړو او ښۀ يې وکتلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_27.mp3', '', 1761754199, 1761754199),
(40883, 'Job 28:28', 'Job', 28, 28, 'او هغۀ بنيادمو ته وفرمائيل، چې د مالِک خُدائ نه يره کښې حِکمت دے، او بدعملى پرېښودل عقلمندى ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job28_verse_28.mp3', '', 1761754199, 1761754199),
(40884, 'Exodus 5:1', 'Exodus', 5, 1, 'بیا موسی او هارون فرعون ته ورغلل او ورته ویې ویل: «د اسراییلو څښتن خدای وایي: ‹زما قوم پرېږده چې دښتې ته لاړ شي او هلته زما د درناوي په خاطر اختر ولمانځي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_1.mp3', '', 1761754199, 1761754199),
(40885, 'Exodus 5:2', 'Exodus', 5, 2, 'فرعون وویل: «څښتن څوک دی؟ زه ولې د هغه خبرو ته غوږ ونیسم او اسراییلیان پرېږدم چې لاړ شي؟ زه څښتن نه پېژنم او نه به اسراییلو ته د تګ اجازه ورکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_2.mp3', '', 1761754199, 1761754199),
(40886, 'Exodus 5:3', 'Exodus', 5, 3, 'هغوی په ځواب کې وویل: «د عبرانیانو خدای مونږ ته راښکاره شوی دی. مونږ پرېږده چې د درېو ورځو دپاره په دښته کې سفر وکړو، ترڅو خپل څښتن خدای ته قرباني وړاندې کړو. که نه، نو هغه به مونږ د ناروغیو او جګړې په وسیله ووژني.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_3.mp3', '', 1761754199, 1761754199),
(40887, 'Exodus 5:4', 'Exodus', 5, 4, 'فرعون موسی او هارون ته وویل: «تاسو ولې خلک له کاره وباسئ؟ هر یو بېرته په خپل کار پسې لاړ شئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_4.mp3', '', 1761754199, 1761754199),
(40888, 'Exodus 5:5', 'Exodus', 5, 5, 'ستاسو شمېر له مصریانو څخه زیات شوی دی او اوس غواړئ چې کار بس کړئ!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_5.mp3', '', 1761754199, 1761754199),
(40889, 'Exodus 5:6', 'Exodus', 5, 6, 'په هماغه ورځ فرعون د غلامانو په مصري مسوولانو او د اسراییلي کارګرانو په مشرانو امر وکړ:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_6.mp3', '', 1761754199, 1761754199),
(40890, 'Exodus 5:7', 'Exodus', 5, 7, '«نور خلکو ته د خښتو جوړولو دپاره بوس مه ورکوئ. هغوی ته ووایئ چې لاړ شي او په خپله یې د ځانونو دپاره پیدا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_7.mp3', '', 1761754199, 1761754199),
(40891, 'Exodus 5:8', 'Exodus', 5, 8, 'خو هغوی باید دومره خښتې جوړې کړي څومره یې چې پخوا جوړولې. هغوی تنبلان دي، ځکه ماته زارۍ کوي چې هغوی پرېږدم چې لاړ شي او خپل خدای ته قرباني وړاندې کړي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_8.mp3', '', 1761754199, 1761754199),
(40892, 'Exodus 5:9', 'Exodus', 5, 9, 'په هغوی باندې سخت کار وکړئ او بوخت یې وساتئ چې د داسې دروغو اورېدلو دپاره وخت ونه لري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_9.mp3', '', 1761754199, 1761754199),
(40893, 'Exodus 5:10', 'Exodus', 5, 10, 'نو د غلامانو مسوولان او د کارګرانو مشران راغلل او ویې ویل: «فرعون وایي: زه به نور تاسو ته بوس درنه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_10.mp3', '', 1761754199, 1761754199),
(40894, 'Exodus 5:11', 'Exodus', 5, 11, 'لاړ شئ او هر چېرته چې کولای شئ د ځانونو دپاره بوس پیدا کړئ، خو بیا به همدومره خښتې جوړوئ څومره چې مو مخکې جوړولې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_11.mp3', '', 1761754199, 1761754199),
(40895, 'Exodus 5:12', 'Exodus', 5, 12, 'نو خلک په ټول مصر کې وګرځېدل، ترڅو د ځانونو دپاره بوس پیدا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_12.mp3', '', 1761754199, 1761754199),
(40896, 'Exodus 5:13', 'Exodus', 5, 13, 'د غلامانو مسوولانو به په هغوی فشار اچاوه او هغوی ته به یې ویل: «تاسو باید هره ورځ دومره خښتې جوړې کړئ څومره چې تاسو هغه وخت جوړولې چې بوس درته درکول کېدل.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_13.mp3', '', 1761754199, 1761754199),
(40897, 'Exodus 5:14', 'Exodus', 5, 14, 'د غلامانو مصري مسوولانو به هغه اسراییلي مشران وهل چې په دوی باندې یې مقرر کړي وو او ورته ویل به یې: «تاسو نن سبا دا غلامان ولې نه مجبوروئ چې دومره خښتې جوړې کړي څومره چې هغوی مخکې جوړولې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_14.mp3', '', 1761754199, 1761754199),
(40898, 'Exodus 5:15', 'Exodus', 5, 15, 'په اخر کې د کارګرانو مشران فرعون ته ورغلل او ورته ویې ویل: «تاسو ولې زمونږ سره داسې چلند کوئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_15.mp3', '', 1761754199, 1761754199),
(40899, 'Exodus 5:16', 'Exodus', 5, 16, 'مونږ ته هېڅوک بوس نه راوړي، خو بیاهم امر راته کیږي چې هماغومره خښتې جوړې کړو. هغوی مونږ وهي، حال دا چې ستاسو خپل خلک ملامت دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_16.mp3', '', 1761754199, 1761754199),
(40900, 'Exodus 5:17', 'Exodus', 5, 17, 'فرعون په ځواب کې وویل: «تاسو تنبلان یئ او نه غواړئ چې کار وکړئ. په دې خاطر ماته وایئ چې تاسو پرېږدم چې لاړ شئ او څښتن ته قرباني وړاندې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_17.mp3', '', 1761754199, 1761754199),
(40901, 'Exodus 5:18', 'Exodus', 5, 18, 'اوس خپل کار پسې لاړ شئ! تاسو ته به بوس نه درکول کیږي، خو بیاهم په هماغه اندازه خښتې جوړې کړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_18.mp3', '', 1761754199, 1761754199),
(40902, 'Exodus 5:19', 'Exodus', 5, 19, 'د کارګرانو مشران پوه شول چې د هغوی حال نور هم خراب شو کله چې فرعون په هغوی امر وکړ چې تاسو به هغومره خښتې جوړوئ لکه مخکې به چې تاسو جوړولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_19.mp3', '', 1761754199, 1761754199),
(40903, 'Exodus 5:20', 'Exodus', 5, 20, 'څنګه چې هغوی د فرعون له دربار څخه ووتل، د موسی او هارون لیدلو ته چې ورته په انتظار وو، لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_20.mp3', '', 1761754199, 1761754199),
(40904, 'Exodus 5:21', 'Exodus', 5, 21, 'هغوی موسی او هارون ته وویل: «تاسو چې څه کړي دي هغه څښتن لیدلي دي او تاسو دواړو ته به سزا درکړي، ځکه چې ستاسو د لاسه فرعون او د هغه درباریان زمونږ څخه کرکه کوي. تاسو هغوی ته بهانه په لاس ورکړه چې مونږ ووژني.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_21.mp3', '', 1761754199, 1761754199),
(40905, 'Exodus 5:22', 'Exodus', 5, 22, 'موسی بېرته څښتن ته ورغی او ویې ویل: «ای څښتنه، ولې دې خپل قوم د بدبختیو سره مخامخ کړی دی؟ ایا زه دې د همدې دپاره رالېږلی یم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_22.mp3', '', 1761754199, 1761754199),
(40906, 'Exodus 5:23', 'Exodus', 5, 23, 'له هغه وخت څخه چې تا ماته وویل چې د فرعون سره خبرې وکړه، هغه ورباندې ظلم کوي او تا د هغوی سره هېڅ مرسته ونه کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus5_verse_23.mp3', '', 1761754199, 1761754199),
(40907, 'Psalms 87:1', 'Psalms', 87, 1, 'څښتن خپل ښار ودان کړ چې یې بنیاد دی ایښی په سپېڅلو تپو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms87_verse_1.mp3', '', 1761754199, 1761754199),
(40908, 'Psalms 87:2', 'Psalms', 87, 2, 'د اسراییلو په ټولو ښارونو کې د صهیون ښار څښتن ته ګران دی له هره ځایه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms87_verse_2.mp3', '', 1761754199, 1761754199),
(40909, 'Psalms 87:3', 'Psalms', 87, 3, 'ای د خدای ښاره خبرې کیږي ستا د جلال په هکله:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms87_verse_3.mp3', '', 1761754199, 1761754199),
(40910, 'Psalms 87:4', 'Psalms', 87, 4, '«مصریان او بابلیان به وشمېرم هغو قومونو کې چې پېژني ما او دغه راز د فلسطین، صور او ایتوپیا خلک دي دوی ټول د اورشلیم ښاریان»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms87_verse_4.mp3', '', 1761754199, 1761754199);